@SuppressWarnings({"varargs", "unchecked", "unused"})
public interface BaseMapper<T> {

    /**
     * 默认批量处理切片数量。
     */
    int DEFAULT_BATCH_SIZE = 1000;

    // === 增（insert） ===

    /**
     * 插入实体类数据，不忽略 {@code null} 值。
     *
