    }

    /**
     * 插入实体类数据，但是忽略 {@code null} 的数据，只对有值的内容进行插入。
     * 这样的好处是数据库已经配置了一些默认值，这些默认值才会生效。
     *
     * @param entity 实体类
     * @return 受影响的行数
     */
    default int insertSelective(T entity) {
        return insert(entity, true);
    }

    /**
     * 插入实体类数据。
